  /* ---------- Favorites, list, finder, festivals, about, footer, messages ---------- */
  S['fav.title'] = ["My Favorites", "என் பிடித்தவை", "എന്റെ ഇഷ്ടങ്ങൾ", "ನನ್ನ ಮೆಚ್ಚಿನವು", "నా ఇష్టమైనవి", "मेरे पसंदीदा"];
  S['fav.emptyTitle'] = ["No favorites yet", "இன்னும் பிடித்தவை இல்லை", "ഇതുവരെ ഇഷ്ടങ്ങളില്ല", "ಇನ್ನೂ ಮೆಚ್ಚಿನವುಗಳಿಲ್ಲ", "ఇంకా ఇష్టమైనవి లేవు", "अभी कोई पसंदीदा नहीं"];
  S['fav.emptyText'] = ["Tap the heart on any recipe to save it here. Favorites stay on this device and need no account.", "எந்த சமையல் குறிப்பிலும் இதயத்தைத் தொட்டு இங்கே சேமியுங்கள். பிடித்தவை இந்தச் சாதனத்திலேயே இருக்கும்; கணக்கு தேவையில்லை.", "ഏതെങ്കിലും പാചകക്കുറിപ്പിലെ ഹൃദയത്തിൽ തൊട്ട് ഇവിടെ സേവ് ചെയ്യുക. ഇഷ്ടങ്ങൾ ഈ ഉപകരണത്തിൽ തന്നെ തുടരും; അക്കൗണ്ട് ആവശ്യമില്ല.", "ಯಾವುದೇ ಪಾಕವಿಧಾನದ ಹೃದಯ ಚಿಹ್ನೆ ಒತ್ತಿ ಇಲ್ಲಿ ಉಳಿಸಿ. ಮೆಚ್ಚಿನವು ಈ ಸಾಧನದಲ್ಲೇ ಇರುತ್ತವೆ; ಖಾತೆ ಬೇಕಿಲ್ಲ.", "ఏ వంటకంపైనైనా హృదయాన్ని నొక్కి ఇక్కడ సేవ్ చేయండి. ఇష్టమైనవి ఈ పరికరంలోనే ఉంటాయి; ఖాతా అవసరం లేదు.", "किसी भी रेसिपी पर दिल दबाकर उसे यहाँ सहेजें। पसंदीदा इसी डिवाइस पर रहते हैं और खाते की ज़रूरत नहीं।"];
  S['fav.added'] = ["Added to favorites", "பிடித்தவையில் சேர்க்கப்பட்டது", "ഇഷ്ടങ്ങളിൽ ചേർത്തു", "ಮೆಚ್ಚಿನವುಗಳಿಗೆ ಸೇರಿಸಲಾಗಿದೆ", "ఇష్టమైన వాటిలో చేర్చబడింది", "पसंदीदा में जोड़ा गया"];
  S['fav.removed'] = ["Removed from favorites", "பிடித்தவையிலிருந்து நீக்கப்பட்டது", "ഇഷ്ടങ്ങളിൽ നിന്ന് നീക്കി", "ಮೆಚ್ಚಿನವುಗಳಿಂದ ತೆಗೆಯಲಾಗಿದೆ", "ఇష్టమైన వాటి నుండి తొలగించబడింది", "पसंदीदा से हटाया गया"];
  S['fav.aria.add'] = ["Add {name} to favorites", "{name} ஐ பிடித்தவையில் சேர்", "{name} ഇഷ്ടങ്ങളിൽ ചേർക്കുക", "{name} ಅನ್ನು ಮೆಚ್ಚಿನವುಗಳಿಗೆ ಸೇರಿಸಿ", "{name} ను ఇష్టమైన వాటిలో చేర్చండి", "{name} को पसंदीदा में जोड़ें"];
