  S['fav.clearHistory'] = ["Clear viewing history", "பார்வை வரலாற்றை அழி", "കണ്ടതിന്റെ ചരിത്രം മായ്ക്കുക", "ವೀಕ್ಷಣೆ ಇತಿಹಾಸ ಅಳಿಸಿ", "వీక్షణ చరిత్రను తొలగించండి", "देखने का इतिहास साफ़ करें"];
  S['list.sub'] = ["Combine ingredients from several recipes into one shopping list. It is saved on this device.", "பல சமையல் குறிப்புகளின் பொருட்களை ஒரே பட்டியலாக இணையுங்கள். இந்தச் சாதனத்தில் சேமிக்கப்படும்.", "പല പാചകക്കുറിപ്പുകളിലെ ചേരുവകൾ ഒറ്റ ഷോപ്പിങ് ലിസ്റ്റാക്കുക. ഈ ഉപകരണത്തിൽ സേവ് ചെയ്യും.", "ಹಲವು ಪಾಕವಿಧಾನಗಳ ಪದಾರ್ಥಗಳನ್ನು ಒಂದೇ ಶಾಪಿಂಗ್ ಪಟ್ಟಿಯಾಗಿ ಸೇರಿಸಿ. ಈ ಸಾಧನದಲ್ಲಿ ಉಳಿಯುತ್ತದೆ.", "అనేక వంటకాల పదార్థాలను ఒకే షాపింగ్ జాబితాగా కలపండి. ఈ పరికరంలో సేవ్ అవుతుంది.", "कई रेसिपी की सामग्री को एक खरीदारी सूची में मिलाएँ। यह इसी डिवाइस पर सहेजी जाती है।"];
  S['list.emptyTitle'] = ["Your list is empty", "உங்கள் பட்டியல் காலியாக உள்ளது", "നിങ്ങളുടെ ലിസ്റ്റ് ശൂന്യമാണ്", "ನಿಮ್ಮ ಪಟ್ಟಿ ಖಾಲಿಯಾಗಿದೆ", "మీ జాబితా ఖాళీగా ఉంది", "आपकी सूची खाली है"];
  S['list.emptyText'] = ["Open a recipe and choose “Add to My Cooking List”.", "ஒரு சமையல் குறிப்பைத் திறந்து “என் சமையல் பட்டியலில் சேர்” என்பதைத் தேர்ந்தெடுங்கள்.", "ഒരു പാചകക്കുറിപ്പ് തുറന്ന് “എന്റെ പാചക ലിസ്റ്റിൽ ചേർക്കുക” തിരഞ്ഞെടുക്കുക.", "ಒಂದು ಪಾಕವಿಧಾನ ತೆರೆದು “ನನ್ನ ಅಡುಗೆ ಪಟ್ಟಿಗೆ ಸೇರಿಸಿ” ಆಯ್ಕೆಮಾಡಿ.", "ఒక వంటకాన్ని తెరిచి “నా వంట జాబితాలో చేర్చండి” ఎంచుకోండి.", "कोई रेसिपी खोलें और “मेरी कुकिंग लिस्ट में जोड़ें” चुनें।"];
  S['list.clear'] = ["Clear list", "பட்டியலை அழி", "ലിസ്റ്റ് മായ്ക്കുക", "ಪಟ್ಟಿ ಅಳಿಸಿ", "జాబితాను తొలగించండి", "सूची साफ़ करें"];
  S['list.clearDone'] = ["Remove ticked items", "குறிக்கப்பட்டவற்றை நீக்கு", "അടയാളപ്പെടുത്തിയവ നീക്കുക", "ಗುರುತಿಸಿದವುಗಳನ್ನು ತೆಗೆಯಿರಿ", "టిక్ చేసినవి తొలగించండి", "निशान लगी चीज़ें हटाएँ"];
