  S['list.copy'] = ["Copy list", "பட்டியலை நகலெடு", "ലിസ്റ്റ് കോപ്പി ചെയ്യുക", "ಪಟ್ಟಿ ನಕಲಿಸಿ", "జాబితాను కాపీ చేయండి", "सूची कॉपी करें"];
  S['list.copied'] = ["List copied", "பட்டியல் நகலெடுக்கப்பட்டது", "ലിസ്റ്റ് കോപ്പി ചെയ്തു", "ಪಟ್ಟಿ ನಕಲಿಸಲಾಗಿದೆ", "జాబితా కాపీ అయింది", "सूची कॉपी हो गई"];
