  S['f.sub'] = ["Pick what you already have. We suggest recipes that use those ingredients.", "உங்களிடம் உள்ளதைத் தேர்ந்தெடுங்கள். அந்தப் பொருட்களைப் பயன்படுத்தும் சமையல் குறிப்புகளைப் பரிந்துரைப்போம்.", "നിങ്ങളുടെ കയ്യിലുള്ളത് തിരഞ്ഞെടുക്കൂ. ആ ചേരുവകൾ ഉപയോഗിക്കുന്ന പാചകക്കുറിപ്പുകൾ ഞങ്ങൾ നിർദേശിക്കാം.", "ನಿಮ್ಮ ಬಳಿ ಇರುವುದನ್ನು ಆರಿಸಿ. ಆ ಪದಾರ್ಥಗಳನ್ನು ಬಳಸುವ ಪಾಕವಿಧಾನಗಳನ್ನು ಸೂಚಿಸುತ್ತೇವೆ.", "మీ దగ్గర ఉన్నవి ఎంచుకోండి. ఆ పదార్థాలను వాడే వంటకాలను సూచిస్తాం.", "जो आपके पास है उसे चुनें। हम उन सामग्रियों वाली रेसिपी सुझाएँगे।"];
  S['f.filter'] = ["Filter ingredients…", "பொருட்களை வடிகட்டு…", "ചേരുവകൾ ഫിൽട്ടർ ചെയ്യുക…", "ಪದಾರ್ಥಗಳನ್ನು ಫಿಲ್ಟರ್ ಮಾಡಿ…", "పదార్థాలను ఫిల్టర్ చేయండి…", "सामग्री फ़िल्टर करें…"];
  S['f.selected'] = ["{n} selected", "{n} தேர்ந்தெடுக்கப்பட்டது", "{n} തിരഞ്ഞെടുത്തു", "{n} ಆಯ್ಕೆಯಾಗಿದೆ", "{n} ఎంచుకున్నారు", "{n} चुने गए"];
  S['f.clear'] = ["Clear selection", "தேர்வை அழி", "തിരഞ്ഞെടുപ്പ് മായ്ക്കുക", "ಆಯ್ಕೆ ಅಳಿಸಿ", "ఎంపికను తొలగించండి", "चयन साफ़ करें"];
  S['f.none'] = ["Select at least one ingredient to see suggestions.", "பரிந்துரைகளைக் காண குறைந்தது ஒரு பொருளைத் தேர்ந்தெடுங்கள்.", "നിർദേശങ്ങൾ കാണാൻ ഒരു ചേരുവയെങ്കിലും തിരഞ്ഞെടുക്കുക.", "ಸಲಹೆಗಳನ್ನು ನೋಡಲು ಕನಿಷ್ಠ ಒಂದು ಪದಾರ್ಥ ಆಯ್ಕೆಮಾಡಿ.", "సూచనలు చూడటానికి కనీసం ఒక పదార్థాన్ని ఎంచుకోండి.", "सुझाव देखने के लिए कम से कम एक सामग्री चुनें।"];
  S['f.noMatch'] = ["No recipe uses these ingredients yet. Try removing one.", "இந்தப் பொருட்களைப் பயன்படுத்தும் சமையல் குறிப்பு இன்னும் இல்லை. ஒன்றை நீக்கி முயலுங்கள்.", "ഈ ചേരുവകൾ ഉപയോഗിക്കുന്ന പാചകക്കുറിപ്പ് ഇതുവരെയില്ല. ഒന്ന് നീക്കി നോക്കൂ.", "ಈ ಪದಾರ್ಥಗಳನ್ನು ಬಳಸುವ ಪಾಕವಿಧಾನ ಇನ್ನೂ ಇಲ್ಲ. ಒಂದನ್ನು ತೆಗೆದು ನೋಡಿ.", "ఈ పదార్థాలను వాడే వంటకం ఇంకా లేదు. ఒకదాన్ని తీసివేసి చూడండి.", "इन सामग्रियों वाली कोई रेसिपी अभी नहीं है। एक हटाकर देखें।"];
  S['f.canCook'] = ["You have everything", "எல்லாப் பொருட்களும் உங்களிடம் உள்ளன", "എല്ലാ ചേരുവകളും നിങ്ങളുടെ കയ്യിലുണ്ട്", "ಎಲ್ಲಾ ಪದಾರ್ಥಗಳೂ ನಿಮ್ಮ ಬಳಿ ಇವೆ", "అన్ని పదార్థాలు మీ దగ్గర ఉన్నాయి", "सारी सामग्री आपके पास है"];
  S['f.have'] = ["You have {a} of {b} ingredients", "{b} பொருட்களில் {a} உங்களிடம் உள்ளன", "{b} ചേരുവകളിൽ {a} നിങ്ങളുടെ കയ്യിലുണ്ട്", "{b} ಪದಾರ್ಥಗಳಲ್ಲಿ {a} ನಿಮ್ಮ ಬಳಿ ಇವೆ", "{b} పదార్థాల్లో {a} మీ దగ్గర ఉన్నాయి", "{b} में से {a} सामग्री आपके पास है"];
  S['f.missing'] = ["Missing: {list}", "இல்லாதவை: {list}", "ഇല്ലാത്തവ: {list}", "ಇಲ್ಲದವು: {list}", "లేనివి: {list}", "कम: {list}"];
  S['f.staples'] = ["Water and salt are assumed to be in your kitchen.", "தண்ணீரும் உப்பும் உங்கள் சமையலறையில் இருப்பதாகக் கருதப்படுகிறது.", "വെള്ളവും ഉപ്പും നിങ്ങളുടെ അടുക്കളയിൽ ഉണ്ടെന്ന് കരുതുന്നു.", "ನೀರು ಮತ್ತು ಉಪ್ಪು ನಿಮ್ಮ ಅಡುಗೆಮನೆಯಲ್ಲಿ ಇವೆ ಎಂದು ಭಾವಿಸಲಾಗಿದೆ.", "నీళ్లు, ఉప్పు మీ వంటగదిలో ఉన్నాయని భావిస్తున్నాం.", "पानी और नमक आपकी रसोई में मौजूद माने गए हैं।"];
  S['fest.sub'] = ["Dishes cooked and shared during South India's festivals.", "தென்னிந்தியப் பண்டிகைகளில் சமைத்துப் பகிரப்படும் உணவுகள்.", "ദക്ഷിണേന്ത്യൻ ഉത്സവങ്ങളിൽ പാകം ചെയ്ത് പങ്കിടുന്ന വിഭവങ്ങൾ.", "ದಕ್ಷಿಣ ಭಾರತದ ಹಬ್ಬಗಳಲ್ಲಿ ಮಾಡಿ ಹಂಚಿಕೊಳ್ಳುವ ಖಾದ್ಯಗಳು.", "దక్షిణ భారత పండుగల్లో వండి పంచుకునే వంటకాలు.", "दक्षिण भारत के त्योहारों में बनने और बाँटे जाने वाले व्यंजन।"];
  S['fest.none'] = ["No recipes for this festival have been added yet.", "இந்தப் பண்டிகைக்கான சமையல் குறிப்புகள் இன்னும் சேர்க்கப்படவில்லை.", "ഈ ഉത്സവത്തിനുള്ള പാചകക്കുറിപ്പുകൾ ഇതുവരെ ചേർത്തിട്ടില്ല.", "ಈ ಹಬ್ಬಕ್ಕೆ ಪಾಕವಿಧಾನಗಳನ್ನು ಇನ್ನೂ ಸೇರಿಸಿಲ್ಲ.", "ఈ పండుగకు వంటకాలు ఇంకా చేర్చలేదు.", "इस त्योहार की रेसिपी अभी नहीं जोड़ी गई हैं।"];
  S['about.p1'] = ["PRIYAM is a home for South Indian cooking: step-by-step recipes from Tamil Nadu, Kerala, Andhra Pradesh, Telangana, Hyderabad and Karnataka, available in six languages.", "PRIYAM தென்னிந்திய சமையலுக்கான ஓர் இல்லம்: தமிழ்நாடு, கேரளா, ஆந்திரப் பிரதேசம், தெலங்கானா, ஹைதராபாத், கர்நாடகா ஆகியவற்றின் படிப்படியான சமையல் குறிப்புகள் ஆறு மொழிகளில்.", "PRIYAM ദക്ഷിണേന്ത്യൻ പാചകത്തിനുള്ള ഒരു വീടാണ്: തമിഴ്‌നാട്, കേരളം, ആന്ധ്രപ്രദേശ്, തെലങ്കാന, ഹൈദരാബാദ്, കർണാടക എന്നിവിടങ്ങളിലെ ഘട്ടം ഘട്ടമായുള്ള പാചകക്കുറിപ്പുകൾ ആറ് ഭാഷകളിൽ.", "PRIYAM ದಕ್ಷಿಣ ಭಾರತೀಯ ಅಡುಗೆಯ ಮನೆ: ತಮಿಳುನಾಡು, ಕೇರಳ, ಆಂಧ್ರ ಪ್ರದೇಶ, ತೆಲಂಗಾಣ, ಹೈದರಾಬಾದ್ ಮತ್ತು ಕರ್ನಾಟಕದ ಹಂತ ಹಂತದ ಪಾಕವಿಧಾನಗಳು ಆರು ಭಾಷೆಗಳಲ್ಲಿ.", "PRIYAM దక్షిణ భారత వంటలకు ఒక ఇల్లు: తమిళనాడు, కేరళ, ఆంధ్రప్రదేశ్, తెలంగాణ, హైదరాబాద్, కర్ణాటకల దశలవారీ వంటకాలు ఆరు భాషల్లో.", "PRIYAM दक्षिण भारतीय खाने का घर है: तमिलनाडु, केरल, आंध्र प्रदेश, तेलंगाना, हैदराबाद और कर्नाटक की चरण-दर-चरण रेसिपी, छह भाषाओं में।"];
  S['about.p2'] = ["The name PRIYAM is personally dedicated to someone special, and the website is made for everyone who loves to cook.", "PRIYAM என்ற பெயர் ஒரு சிறப்பு நபருக்காக அர்ப்பணிக்கப்பட்டது; இந்த இணையதளம் சமைக்க விரும்பும் அனைவருக்குமானது.", "PRIYAM എന്ന പേര് ഒരു പ്രത്യേക വ്യക്തിക്കായി സമർപ്പിച്ചതാണ്; ഈ വെബ്സൈറ്റ് പാചകം ഇഷ്ടപ്പെടുന്ന എല്ലാവർക്കുമുള്ളതാണ്.", "PRIYAM ಹೆಸರನ್ನು ವಿಶೇಷ ವ್ಯಕ್ತಿಗೆ ಅರ್ಪಿಸಲಾಗಿದೆ; ಈ ವೆಬ್‌ಸೈಟ್ ಅಡುಗೆ ಇಷ್ಟಪಡುವ ಎಲ್ಲರಿಗಾಗಿ.", "PRIYAM పేరు ఒక ప్రత్యేక వ్యక్తికి అంకితం; ఈ వెబ్‌సైట్ వంటను ఇష్టపడే అందరి కోసం.", "PRIYAM नाम किसी खास व्यक्ति को समर्पित है, और यह वेबसाइट खाना पकाने के शौकीन हर किसी के लिए है।"];
  S['about.p3'] = ["Recipes and translations are written by the PRIYAM team and are not verified by professional chefs. Nutrition values are estimates. Please check allergens and food-safety guidance for your own household.", "சமையல் குறிப்புகளும் மொழிபெயர்ப்புகளும் PRIYAM குழுவால் எழுதப்பட்டவை; தொழில்முறை சமையல் கலைஞர்களால் சரிபார்க்கப்படவில்லை. ஊட்டச்சத்து மதிப்புகள் மதிப்பீடுகளே. உங்கள் வீட்டுக்கான ஒவ்வாமை மற்றும் உணவுப் பாதுகாப்பு வழிகாட்டுதல்களைச் சரிபாருங்கள்.", "പാചകക്കുറിപ്പുകളും വിവർത്തനങ്ങളും PRIYAM ടീം എഴുതിയതാണ്; പ്രൊഫഷണൽ ഷെഫുകൾ പരിശോധിച്ചിട്ടില്ല. പോഷക മൂല്യങ്ങൾ ഏകദേശ കണക്കുകളാണ്. നിങ്ങളുടെ വീട്ടിലെ അലർജിയും ഭക്ഷ്യസുരക്ഷാ നിർദേശങ്ങളും പരിശോധിക്കുക.", "ಪಾಕವಿಧಾನಗಳು ಮತ್ತು ಅನುವಾದಗಳನ್ನು PRIYAM ತಂಡ ಬರೆದಿದೆ; ವೃತ್ತಿಪರ ಬಾಣಸಿಗರಿಂದ ಪರಿಶೀಲಿಸಲಾಗಿಲ್ಲ. ಪೌಷ್ಟಿಕಾಂಶ ಮೌಲ್ಯಗಳು ಅಂದಾಜು. ನಿಮ್ಮ ಮನೆಗೆ ಅಲರ್ಜಿ ಮತ್ತು ಆಹಾರ ಸುರಕ್ಷತೆ ಮಾರ್ಗದರ್ಶನ ಪರಿಶೀಲಿಸಿ.", "వంటకాలు, అనువాదాలను PRIYAM బృందం రాసింది; ప్రొఫెషనల్ చెఫ్‌లు ధృవీకరించలేదు. పోషక విలువలు అంచనాలు మాత్రమే. మీ ఇంటికి అలర్జీ, ఆహార భద్రత సూచనలను సరిచూసుకోండి.", "रेसिपी और अनुवाद प्रियम टीम ने लिखे हैं और पेशेवर शेफ़ द्वारा सत्यापित नहीं हैं। पोषण मान अनुमानित हैं। अपने घर के लिए एलर्जन और खाद्य-सुरक्षा निर्देश ज़रूर जाँचें।"];
  S['about.p4'] = ["Favorites and your cooking list are stored only in this browser. Nothing is sent to a server.", "பிடித்தவையும் சமையல் பட்டியலும் இந்த உலாவியில் மட்டுமே சேமிக்கப்படும். எதுவும் சர்வருக்கு அனுப்பப்படாது.", "ഇഷ്ടങ്ങളും പാചക ലിസ്റ്റും ഈ ബ്രൗസറിൽ മാത്രമാണ് സൂക്ഷിക്കുന്നത്. ഒന്നും സെർവറിലേക്ക് അയയ്ക്കുന്നില്ല.", "ಮೆಚ್ಚಿನವು ಮತ್ತು ಅಡುಗೆ ಪಟ್ಟಿ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಸಂಗ್ರಹವಾಗುತ್ತವೆ. ಯಾವುದನ್ನೂ ಸರ್ವರ್‌ಗೆ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.", "ఇష్టమైనవి, వంట జాబితా ఈ బ్రౌజర్‌లో మాత్రమే నిల్వ అవుతాయి. ఏదీ సర్వర్‌కు పంపబడదు.", "पसंदीदा और कुकिंग लिस्ट सिर्फ़ इसी ब्राउज़र में रहती हैं। कुछ भी सर्वर को नहीं भेजा जाता।"];
  S['ft.explore'] = ["Explore", "ஆராய்க", "പര്യവേക്ഷണം", "ಅನ್ವೇಷಿಸಿ", "అన్వేషించండి", "खोजें"];
  S['ft.rights'] = ["PRIYAM. Recipes written for home cooks.", "PRIYAM. வீட்டுச் சமையலுக்காக எழுதப்பட்ட சமையல் குறிப்புகள்.", "PRIYAM. വീട്ടിലെ പാചകക്കാർക്കായി എഴുതിയ പാചകക്കുറിപ്പുകൾ.", "PRIYAM. ಮನೆ ಅಡುಗೆಯವರಿಗಾಗಿ ಬರೆದ ಪಾಕವಿಧಾನಗಳು.", "PRIYAM. ఇంటి వంటవారి కోసం రాసిన వంటకాలు.", "PRIYAM. घर पर पकाने वालों के लिए लिखी गई रेसिपी।"];
  S['ft.note'] = ["Nutrition values are approximate. Always check allergens for your household.", "ஊட்டச்சத்து மதிப்புகள் தோராயமானவை. உங்கள் வீட்டுக்கான ஒவ்வாமைகளை எப்போதும் சரிபாருங்கள்.", "പോഷക മൂല്യങ്ങൾ ഏകദേശമാണ്. നിങ്ങളുടെ വീട്ടിലെ അലർജികൾ എപ്പോഴും പരിശോധിക്കുക.", "ಪೌಷ್ಟಿಕಾಂಶ ಮೌಲ್ಯಗಳು ಅಂದಾಜು. ನಿಮ್ಮ ಮನೆಯ ಅಲರ್ಜಿಗಳನ್ನು ಯಾವಾಗಲೂ ಪರಿಶೀಲಿಸಿ.", "పోషక విలువలు అంచనాలే. మీ ఇంటి అలర్జీలను ఎల్లప్పుడూ చూసుకోండి.", "पोषण मान अनुमानित हैं। अपने घर के लिए एलर्जन हमेशा जाँचें।"];
  S['msg.linkCopied'] = ["Link copied to clipboard", "இணைப்பு நகலெடுக்கப்பட்டது", "ലിങ്ക് കോപ്പി ചെയ്തു", "ಲಿಂಕ್ ನಕಲಿಸಲಾಗಿದೆ", "లింక్ కాపీ అయింది", "लिंक कॉपी हो गया"];
  S['msg.shareFail'] = ["Sharing is not available. Copy the address from your browser instead.", "பகிர்வு கிடைக்கவில்லை. உலாவியின் முகவரியை நகலெடுக்கவும்.", "പങ്കിടൽ ലഭ്യമല്ല. ബ്രൗസറിലെ വിലാസം കോപ്പി ചെയ്യുക.", "ಹಂಚಿಕೆ ಲಭ್ಯವಿಲ್ಲ. ಬದಲಿಗೆ ಬ್ರೌಸರ್‌ನ ವಿಳಾಸ ನಕಲಿಸಿ.", "షేరింగ్ అందుబాటులో లేదు. బ్రౌజర్ చిరునామాను కాపీ చేయండి.", "साझा करना उपलब्ध नहीं है। ब्राउज़र का पता कॉपी करें।"];
  S['msg.storageBlocked'] = ["Your browser blocked saving data, so favorites and lists will be lost when you close this page.", "உங்கள் உலாவி தரவைச் சேமிக்கத் தடுத்துள்ளது; இந்தப் பக்கத்தை மூடினால் பிடித்தவையும் பட்டியல்களும் இழக்கப்படும்.", "നിങ്ങളുടെ ബ്രൗസർ ഡാറ്റ സേവ് ചെയ്യുന്നത് തടഞ്ഞു; ഈ പേജ് അടച്ചാൽ ഇഷ്ടങ്ങളും ലിസ്റ്റുകളും നഷ്ടമാകും.", "ನಿಮ್ಮ ಬ್ರೌಸರ್ ಡೇಟಾ ಉಳಿಸುವುದನ್ನು ತಡೆದಿದೆ; ಈ ಪುಟ ಮುಚ್ಚಿದರೆ ಮೆಚ್ಚಿನವು ಮತ್ತು ಪಟ್ಟಿಗಳು ಕಳೆದುಹೋಗುತ್ತವೆ.", "మీ బ్రౌజర్ డేటా సేవింగ్‌ను నిరోధించింది; ఈ పేజీ మూసివేస్తే ఇష్టమైనవి, జాబితాలు పోతాయి.", "आपके ब्राउज़र ने डेटा सहेजना रोक दिया है, इसलिए पेज बंद करने पर पसंदीदा और सूचियाँ खो जाएँगी।"];
  S['msg.error'] = ["Something went wrong while showing this page. Go back to the home page and try again.", "இந்தப் பக்கத்தைக் காட்டும்போது ஏதோ தவறு நடந்தது. முகப்புக்குச் சென்று மீண்டும் முயலுங்கள்.", "ഈ പേജ് കാണിക്കുമ്പോൾ എന്തോ തെറ്റ് സംഭവിച്ചു. ഹോമിലേക്ക് പോയി വീണ്ടും ശ്രമിക്കുക.", "ಈ ಪುಟ ತೋರಿಸುವಾಗ ಏನೋ ತಪ್ಪಾಗಿದೆ. ಮುಖಪುಟಕ್ಕೆ ಹೋಗಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.", "ఈ పేజీని చూపిస్తున్నప్పుడు ఏదో తప్పు జరిగింది. హోమ్‌కు వెళ్లి మళ్లీ ప్రయత్నించండి.", "यह पेज दिखाते समय कुछ गड़बड़ हुई। होम पेज पर जाकर फिर कोशिश करें।"];
  S['nf.title'] = ["We couldn't find that page", "அந்தப் பக்கத்தைக் காண முடியவில்லை", "ആ പേജ് കണ്ടെത്താനായില്ല", "ಆ ಪುಟ ಸಿಗಲಿಲ್ಲ", "ఆ పేజీ దొరకలేదు", "वह पेज नहीं मिला"];
  S['nf.text'] = ["The link may be old, or the recipe may have been renamed.", "இணைப்பு பழையதாக இருக்கலாம் அல்லது சமையல் குறிப்பின் பெயர் மாறியிருக்கலாம்.", "ലിങ്ക് പഴയതാകാം, അല്ലെങ്കിൽ പാചകക്കുറിപ്പിന്റെ പേര് മാറിയിരിക്കാം.", "ಲಿಂಕ್ ಹಳೆಯದಾಗಿರಬಹುದು ಅಥವಾ ಪಾಕವಿಧಾನದ ಹೆಸರು ಬದಲಾಗಿರಬಹುದು.", "లింక్ పాతది కావచ్చు లేదా వంటకం పేరు మారి ఉండవచ్చు.", "लिंक पुराना हो सकता है या रेसिपी का नाम बदल गया हो।"];
  S['common.loading'] = ["Loading recipes…", "சமையல் குறிப்புகள் ஏற்றப்படுகின்றன…", "പാചകക്കുറിപ്പുകൾ ലോഡ് ചെയ്യുന്നു…", "ಪಾಕವಿಧಾನಗಳು ಲೋಡ್ ಆಗುತ್ತಿವೆ…", "వంటకాలు లోడ్ అవుతున్నాయి…", "रेसिपी लोड हो रही हैं…"];
  S['common.backHome'] = ["Back to home", "முகப்புக்குத் திரும்பு", "ഹോമിലേക്ക് മടങ്ങുക", "ಮುಖಪುಟಕ್ಕೆ ಹಿಂತಿರುಗಿ", "హోమ్‌కు తిరిగి వెళ్లండి", "होम पर वापस जाएँ"];
  S['common.noscript'] = ["PRIYAM needs JavaScript to show recipes. Please enable JavaScript in your browser.", "சமையல் குறிப்புகளைக் காட்ட PRIYAM க்கு JavaScript தேவை. உங்கள் உலாவியில் JavaScript ஐ இயக்குங்கள்.", "പാചകക്കുറിപ്പുകൾ കാണിക്കാൻ PRIYAM ന് JavaScript ആവശ്യമാണ്. ബ്രൗസറിൽ JavaScript പ്രവർത്തനക്ഷമമാക്കുക.", "ಪಾಕವಿಧಾನಗಳನ್ನು ತೋರಿಸಲು PRIYAM ಗೆ JavaScript ಬೇಕು. ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನಲ್ಲಿ JavaScript ಸಕ್ರಿಯಗೊಳಿಸಿ.", "వంటకాలను చూపడానికి PRIYAM కు JavaScript అవసరం. మీ బ్రౌజర్‌లో JavaScript ను ప్రారంభించండి.", "रेसिपी दिखाने के लिए PRIYAM को JavaScript चाहिए। कृपया अपने ब्राउज़र में JavaScript चालू करें।"];
  S['region.signature'] = ["Signature dishes", "சிறப்பு உணவுகள்", "പ്രധാന വിഭവങ്ങൾ", "ವಿಶಿಷ್ಟ ಖಾದ್ಯಗಳು", "ప్రత్యేక వంటకాలు", "खास व्यंजन"];
  S['region.ingredients'] = ["Common local ingredients", "உள்ளூரில் பொதுவான பொருட்கள்", "പ്രാദേശികമായി സാധാരണ ചേരുവകൾ", "ಸ್ಥಳೀಯ ಸಾಮಾನ್ಯ ಪದಾರ್ಥಗಳು", "స్థానికంగా సాధారణ పదార్థాలు", "आम स्थानीय सामग्री"];
  S['region.techniques'] = ["Traditional cooking techniques", "பாரம்பரிய சமையல் நுட்பங்கள்", "പരമ്പരാഗത പാചക രീതികൾ", "ಸಾಂಪ್ರದಾಯಿಕ ಅಡುಗೆ ತಂತ್ರಗಳು", "సంప్రదాయ వంట పద్ధతులు", "पारंपरिक पकाने की तकनीकें"];
  S['region.allRecipes'] = ["All {region} recipes", "{region} சமையல் குறிப்புகள் அனைத்தும்", "{region} പാചകക്കുറിപ്പുകൾ എല്ലാം", "{region} ಎಲ್ಲಾ ಪಾಕವಿಧಾನಗಳು", "{region} వంటకాలన్నీ", "{region} की सभी रेसिपी"];
  S['region.none'] = ["Recipes for this kitchen are still being added.", "இந்தச் சமையலறைக்கான சமையல் குறிப்புகள் இன்னும் சேர்க்கப்பட்டு வருகின்றன.", "ഈ അടുക്കളയ്ക്കുള്ള പാചകക്കുറിപ്പുകൾ ഇപ്പോഴും ചേർത്തുകൊണ്ടിരിക്കുന്നു.", "ಈ ಅಡುಗೆಮನೆಯ ಪಾಕವಿಧಾನಗಳನ್ನು ಇನ್ನೂ ಸೇರಿಸಲಾಗುತ್ತಿದೆ.", "ఈ వంటశాల వంటకాలు ఇంకా చేర్చబడుతున్నాయి.", "इस रसोई की रेसिपी अभी जोड़ी जा रही हैं।"];

