  S['category.curries'] = ["Curries and Gravies", "குழம்பு மற்றும் கறி வகைகள்", "കറികളും ഗ്രേവികളും", "ಕರಿ ಮತ್ತು ಗ್ರೇವಿಗಳು", "కూరలు మరియు గ్రేవీలు", "करी और ग्रेवी"];
  S['category.chutneys-pickles'] = ["Chutneys and Pickles", "சட்னி மற்றும் ஊறுகாய்", "ചട്ണികളും അച്ചാറുകളും", "ಚಟ್ನಿ ಮತ್ತು ಉಪ್ಪಿನಕಾಯಿ", "చట్నీలు మరియు పచ్చళ్లు", "चटनी और अचार"];
  S['category.traditional-sweets'] = ["Traditional Sweets", "பாரம்பரிய இனிப்புகள்", "പരമ്പരാഗത മധുരങ്ങൾ", "ಸಾಂಪ್ರದಾಯಿಕ ಸಿಹಿಗಳು", "సంప్రదాయ స్వీట్లు", "पारंपरिक मिठाइयाँ"];
  S['category.beverages'] = ["Beverages", "பானங்கள்", "പാനീയങ്ങൾ", "ಪಾನೀಯಗಳು", "పానీయాలు", "पेय"];
  S['category.festival'] = ["Festival Specials", "பண்டிகை சிறப்புகள்", "ഉത്സവ വിഭവങ്ങൾ", "ಹಬ್ಬದ ವಿಶೇಷಗಳು", "పండుగ ప్రత్యేకతలు", "त्योहार विशेष"];
  S['category.vegetarian'] = ["Vegetarian", "சைவம்", "വെജിറ്റേറിയൻ", "ಸಸ್ಯಾಹಾರ", "శాకాహారం", "शाकाहारी"];
