  /* ---------- Festivals ---------- */
  S['festival.pongal.name'] = ["Pongal", "பொங்கல்", "പൊങ്കൽ", "ಪೊಂಗಲ್", "పొంగల్", "पोंगल"];
  S['festival.pongal.desc'] = ["Tamil harvest festival in January, when freshly cooked rice is offered in thanks to the sun and the farm.", "ஜனவரியில் கொண்டாடப்படும் தமிழ் அறுவடைத் திருநாள்; புதிய அரிசியைச் சமைத்து சூரியனுக்கும் உழவுக்கும் நன்றி செலுத்தும் பண்டிகை.", "ജനുവരിയിൽ ആഘോഷിക്കുന്ന തമിഴ് വിളവെടുപ്പ് ഉത്സവം; പുതിയ അരി വേവിച്ച് സൂര്യനും കൃഷിക്കും നന്ദി അർപ്പിക്കുന്നു.", "ಜನವರಿಯಲ್ಲಿ ಆಚರಿಸುವ ತಮಿಳು ಸುಗ್ಗಿ ಹಬ್ಬ; ಹೊಸ ಅಕ್ಕಿಯನ್ನು ಬೇಯಿಸಿ ಸೂರ್ಯನಿಗೂ ಕೃಷಿಗೂ ಕೃತಜ್ಞತೆ ಸಲ್ಲಿಸಲಾಗುತ್ತದೆ.", "జనవరిలో జరుపుకునే తమిళ పంటల పండుగ; కొత్త బియ్యం వండి సూర్యుడికి, వ్యవసాయానికి కృతజ్ఞతలు తెలుపుతారు.", "जनवरी में मनाया जाने वाला तमिल फसल उत्सव, जिसमें नए चावल को पकाकर सूर्य और खेती के प्रति आभार जताया जाता है।"];
  S['festival.onam.name'] = ["Onam", "ஓணம்", "ഓണം", "ಓಣಂ", "ఓనం", "ओणम"];
  S['festival.onam.desc'] = ["Kerala's harvest festival, celebrated with the sadya, a many-course vegetarian feast served on a banana leaf.", "கேரளாவின் அறுவடைத் திருவிழா; வாழை இலையில் பரிமாறப்படும் பல வகை சைவ விருந்தான சத்யாவுடன் கொண்டாடப்படுகிறது.", "കേരളത്തിന്റെ വിളവെടുപ്പ് ഉത്സവം; വാഴയിലയിൽ വിളമ്പുന്ന പലവിധ വിഭവങ്ങളുള്ള സസ്യാഹാര സദ്യയോടെ ആഘോഷിക്കുന്നു.", "ಕೇರಳದ ಸುಗ್ಗಿ ಹಬ್ಬ; ಬಾಳೆ ಎಲೆಯಲ್ಲಿ ಬಡಿಸುವ ಅನೇಕ ಖಾದ್ಯಗಳ ಸಸ್ಯಾಹಾರಿ ಸದ್ಯದೊಂದಿಗೆ ಆಚರಿಸಲಾಗುತ್ತದೆ.", "కేరళ పంటల పండుగ; అరటి ఆకులో వడ్డించే అనేక వంటకాల శాకాహార విందు 'సద్య'తో జరుపుకుంటారు.", "केरल का फसल उत्सव, जिसे केले के पत्ते पर परोसी जाने वाली कई व्यंजनों की शाकाहारी दावत 'सद्या' के साथ मनाया जाता है।"];
  S['festival.ugadi.name'] = ["Ugadi", "உகாதி", "ഉഗാദി", "ಯುಗಾದಿ", "ఉగాది", "उगादी"];
  S['festival.ugadi.desc'] = ["New Year in Andhra Pradesh, Telangana and Karnataka, marked by a dish that combines six tastes, symbolising the mix of life's experiences.", "ஆந்திரா, தெலங்கானா, கர்நாடகாவில் கொண்டாடப்படும் புத்தாண்டு; வாழ்வின் பல அனுபவங்களைக் குறிக்கும் ஆறு சுவைகள் இணைந்த உணவுடன் கொண்டாடப்படுகிறது.", "ആന്ധ്ര, തെലങ്കാന, കർണാടക എന്നിവിടങ്ങളിലെ പുതുവർഷം; ജീവിതാനുഭവങ്ങളുടെ കൂട്ടായ്മയെ സൂചിപ്പിക്കുന്ന ആറ് രുചികൾ ചേർന്ന വിഭവത്തോടെ ആഘോഷിക്കുന്നു.", "ಆಂಧ್ರ ಪ್ರದೇಶ, ತೆಲಂಗಾಣ ಮತ್ತು ಕರ್ನಾಟಕದ ಹೊಸ ವರ್ಷ; ಜೀವನದ ಅನುಭವಗಳ ಮಿಶ್ರಣವನ್ನು ಸೂಚಿಸುವ ಆರು ರುಚಿಗಳ ಖಾದ್ಯದೊಂದಿಗೆ ಆಚರಿಸಲಾಗುತ್ತದೆ.", "ఆంధ్రప్రదేశ్, తెలంగాణ, కర్ణాటకలో జరుపుకునే కొత్త సంవత్సరం; జీవిత అనుభవాల మిశ్రమాన్ని సూచించే ఆరు రుచుల వంటకంతో జరుపుకుంటారు.", "आंध्र प्रदेश, तेलंगाना और कर्नाटक का नववर्ष, जिसमें जीवन के अनुभवों के मेल का प्रतीक छह स्वादों वाला व्यंजन बनता है।"];
  S['festival.deepavali.name'] = ["Deepavali", "தீபாவளி", "ദീപാവലി", "ದೀಪಾವಳಿ", "దీపావళి", "दीपावली"];
  S['festival.deepavali.desc'] = ["The festival of lights, celebrated across South India with homemade sweets and savouries shared with family and neighbours.", "தீபங்களின் திருநாள்; வீட்டில் செய்த இனிப்பு, காரப் பலகாரங்களை குடும்பத்தினருடனும் அண்டை வீட்டாருடனும் பகிர்ந்து தென்னிந்தியா முழுவதும் கொண்டாடப்படுகிறது.", "ദീപങ്ങളുടെ ഉത്സവം; വീട്ടിൽ ഉണ്ടാക്കിയ മധുരങ്ങളും പലഹാരങ്ങളും കുടുംബത്തോടും അയൽക്കാരോടും പങ്കുവച്ച് ദക്ഷിണേന്ത്യയിലുടനീളം ആഘോഷിക്കുന്നു.", "ದೀಪಗಳ ಹಬ್ಬ; ಮನೆಯಲ್ಲಿ ಮಾಡಿದ ಸಿಹಿ ಮತ್ತು ಖಾರದ ತಿಂಡಿಗಳನ್ನು ಕುಟುಂಬ ಹಾಗೂ ನೆರೆಹೊರೆಯವರೊಂದಿಗೆ ಹಂಚಿಕೊಂಡು ದಕ್ಷಿಣ ಭಾರತದಾದ್ಯಂತ ಆಚರಿಸಲಾಗುತ್ತದೆ.", "దీపాల పండుగ; ఇంట్లో చేసిన స్వీట్లు, కారప్పూసలను కుటుంబం, ఇరుగుపొరుగుతో పంచుకుంటూ దక్షిణ భారతదేశమంతటా జరుపుకుంటారు.", "रोशनी का त्योहार, जिसे पूरे दक्षिण भारत में घर की बनी मिठाइयों और नमकीन को परिवार और पड़ोसियों के साथ बाँटकर मनाया जाता है।"];
  S['festival.ramzan.name'] = ["Ramzan (Eid)", "ரம்ஜான் (ஈத்)", "റംസാൻ (ഈദ്)", "ರಂಜಾನ್ (ಈದ್)", "రంజాన్ (ఈద్)", "रमज़ान (ईद)"];
  S['festival.ramzan.desc'] = ["The month of fasting and the Eid celebrations that follow, with Hyderabad famous for haleem and festive sweets.", "நோன்பு மாதமும் அதைத் தொடரும் ஈத் கொண்டாட்டங்களும்; ஹைதராபாத் ஹலீம் மற்றும் பண்டிகை இனிப்புகளுக்குப் புகழ்பெற்றது.", "നോമ്പ് മാസവും തുടർന്നുള്ള ഈദ് ആഘോഷങ്ങളും; ഹലീമിനും ഉത്സവ മധുരങ്ങൾക്കും ഹൈദരാബാദ് പ്രശസ്തമാണ്.", "ಉಪವಾಸದ ತಿಂಗಳು ಮತ್ತು ನಂತರದ ಈದ್ ಆಚರಣೆಗಳು; ಹೈದರಾಬಾದ್ ಹಲೀಮ್ ಮತ್ತು ಹಬ್ಬದ ಸಿಹಿಗಳಿಗೆ ಪ್ರಸಿದ್ಧ.", "ఉపవాస మాసం, ఆ తరువాత ఈద్ వేడుకలు; హైదరాబాద్ హలీమ్‌కు, పండుగ మిఠాయిలకు ప్రసిద్ధి.", "रोज़े का महीना और उसके बाद ईद का जश्न; हैदराबाद हलीम और त्योहारी मिठाइयों के लिए मशहूर है।"];

  /* ---------- Regions ---------- */
  S['region.tamil-nadu.name'] = ["Tamil Nadu", "தமிழ்நாடு", "തമിഴ്‌നാട്", "ತಮಿಳುನಾಡು", "తమిళనాడు", "तमिलनाडु"];
  S['region.tamil-nadu.intro'] = ["Rice, lentils and bold spice, from temple kitchens to Chettinad feasts.", "அரிசி, பருப்பு, துணிச்சலான மசாலா — கோயில் சமையலறைகள் முதல் செட்டிநாட்டு விருந்துகள் வரை.", "അരി, പരിപ്പ്, തീക്ഷ്ണ മസാലകൾ — ക്ഷേത്ര അടുക്കളകൾ മുതൽ ചെട്ടിനാട് സദ്യ വരെ.", "ಅಕ್ಕಿ, ಬೇಳೆ, ಖಾರದ ಮಸಾಲೆ — ದೇವಾಲಯದ ಅಡುಗೆಮನೆಗಳಿಂದ ಚೆಟ್ಟಿನಾಡು ಭೋಜನಗಳವರೆಗೆ.", "బియ్యం, పప్పులు, ఘాటైన మసాలాలు — ఆలయ వంటశాలల నుండి చెట్టినాడు విందుల వరకు.", "चावल, दालें और तीखे मसाले — मंदिर की रसोई से चेट्टीनाड की दावतों तक।"];
  S['region.tamil-nadu.about'] = ["From everyday idli, dosa and sambar to fiery Chettinad curries and temple offerings, Tamil Nadu's meals are traditionally served on a banana leaf with rice at the centre.", "அன்றாட இட்லி, தோசை, சாம்பார் முதல் செட்டிநாட்டின் காரமான குழம்புகள் மற்றும் கோயில் பிரசாதங்கள் வரை, தமிழ்நாட்டு உணவு பாரம்பரியமாக வாழை இலையில் நடுவில் சாதத்துடன் பரிமாறப்படுகிறது.", "ദിവസേനയുള്ള ഇഡ്ഡലി, ദോശ, സാമ്പാർ മുതൽ എരിവേറിയ ചെട്ടിനാട് കറികളും ക്ഷേത്ര പ്രസാദങ്ങളും വരെ; തമിഴ്‌നാട്ടിലെ ഭക്ഷണം പരമ്പരാഗതമായി വാഴയിലയിൽ നടുവിൽ ചോറുവച്ച് വിളമ്പുന്നു.", "ದಿನನಿತ್ಯದ ಇಡ್ಲಿ, ದೋಸೆ, ಸಾಂಬಾರ್‌ನಿಂದ ಖಾರದ ಚೆಟ್ಟಿನಾಡು ಕರಿಗಳು ಮತ್ತು ದೇವಾಲಯ ಪ್ರಸಾದಗಳವರೆಗೆ, ತಮಿಳುನಾಡಿನ ಊಟವನ್ನು ಸಾಂಪ್ರದಾಯಿಕವಾಗಿ ಬಾಳೆ ಎಲೆಯಲ್ಲಿ ಮಧ್ಯದಲ್ಲಿ ಅನ್ನವಿಟ್ಟು ಬಡಿಸಲಾಗುತ್ತದೆ.", "రోజువారీ ఇడ్లీ, దోశ, సాంబార్ నుండి ఘాటైన చెట్టినాడు కూరలు, ఆలయ ప్రసాదాల వరకు; తమిళనాడు భోజనాన్ని సంప్రదాయంగా అరటి ఆకులో మధ్యలో అన్నం పెట్టి వడ్డిస్తారు.", "रोज़ के इडली, डोसा और सांभर से लेकर तीखी चेट्टीनाड करी और मंदिर के प्रसाद तक; तमिलनाडु का भोजन परंपरागत रूप से केले के पत्ते पर बीच में चावल रखकर परोसा जाता है।"];
  S['region.tamil-nadu.ingredients'] = [["Rice", "Toor dal and urad dal", "Tamarind", "Sesame (gingelly) oil", "Curry leaves", "Shallots"], ["அரிசி", "துவரம் பருப்பு, உளுந்து", "புளி", "நல்லெண்ணெய்", "கறிவேப்பிலை", "சின்ன வெங்காயம்"], ["അരി", "തുവരപ്പരിപ്പ്, ഉഴുന്ന്", "പുളി", "നല്ലെണ്ണ (എള്ളെണ്ണ)", "കറിവേപ്പില", "ചെറിയ ഉള്ളി"], ["ಅಕ್ಕಿ", "ತೊಗರಿ ಬೇಳೆ, ಉದ್ದಿನ ಬೇಳೆ", "ಹುಣಸೆಹಣ್ಣು", "ಎಳ್ಳೆಣ್ಣೆ", "ಕರಿಬೇವು", "ಸಣ್ಣ ಈರುಳ್ಳಿ"], ["బియ్యం", "కందిపప్పు, మినప్పప్పు", "చింతపండు", "నువ్వుల నూనె", "కరివేపాకు", "చిన్న ఉల్లిపాయలు"], ["चावल", "अरहर और उड़द दाल", "इमली", "तिल का तेल", "कढ़ी पत्ता", "छोटे प्याज़"]];
  S['region.tamil-nadu.techniques'] = [["Fermenting batter for idli and dosa", "Tempering (thalippu) in hot oil or ghee", "Slow-simmering tamarind kuzhambu"], ["இட்லி, தோசை மாவை புளிக்க வைத்தல்", "சூடான எண்ணெய் அல்லது நெய்யில் தாளித்தல்", "புளிக் குழம்பை மெல்லிய தீயில் கொதிக்க வைத்தல்"], ["ഇഡ്ഡലി, ദോശ മാവ് പുളിപ്പിക്കൽ", "ചൂടുള്ള എണ്ണയിലോ നെയ്യിലോ താളിക്കൽ", "പുളിക്കറി (കുഴമ്പ്) മെല്ലെ തിളപ്പിക്കൽ"], ["ಇಡ್ಲಿ, ದೋಸೆ ಹಿಟ್ಟನ್ನು ಹುದುಗಿಸುವುದು", "ಬಿಸಿ ಎಣ್ಣೆ ಅಥವಾ ತುಪ್ಪದಲ್ಲಿ ಒಗ್ಗರಣೆ ಹಾಕುವುದು", "ಹುಣಸೆ ಕುಳಂಬನ್ನು ಸಣ್ಣ ಉರಿಯಲ್ಲಿ ಕುದಿಸುವುದು"], ["ఇడ్లీ, దోశ పిండిని పులియబెట్టడం", "వేడి నూనె లేదా నెయ్యిలో తాళింపు", "చింతపండు కుళంబును చిన్న మంటపై ఉడికించడం"], ["इडली-डोसा के घोल को खमीर उठाना", "गर्म तेल या घी में तड़का लगाना", "इमली की कुळंबु को धीमी आँच पर पकाना"]];

  S['region.kerala.name'] = ["Kerala", "கேரளா", "കേരളം", "ಕೇರಳ", "కేరళ", "केरल"];
  S['region.kerala.intro'] = ["Coconut, coconut oil, curry leaves and the spices of the Malabar coast.", "தேங்காய், தேங்காய் எண்ணெய், கறிவேப்பிலை, மலபார் கடற்கரையின் மசாலாக்கள்.", "തേങ്ങ, വെളിച്ചെണ്ണ, കറിവേപ്പില, മലബാർ തീരത്തെ സുഗന്ധവ്യഞ്ജനങ്ങൾ.", "ತೆಂಗಿನಕಾಯಿ, ಕೊಬ್ಬರಿ ಎಣ್ಣೆ, ಕರಿಬೇವು ಮತ್ತು ಮಲಬಾರ್ ಕರಾವಳಿಯ ಮಸಾಲೆಗಳು.", "కొబ్బరి, కొబ్బరి నూనె, కరివేపాకు, మలబార్ తీరపు సుగంధ ద్రవ్యాలు.", "नारियल, नारियल तेल, कढ़ी पत्ता और मालाबार तट के मसाले।"];
  S['region.kerala.about'] = ["Kerala cooks with coconut in many forms, alongside black pepper, kodampuli and plenty of fresh fish. The festive sadya is a many-dish vegetarian meal served on a banana leaf.", "கேரள சமையலில் தேங்காய் பல வடிவங்களில் பயன்படுகிறது; கூடவே மிளகு, குடம்புளி, ஏராளமான புதிய மீன். பண்டிகை சத்யா வாழை இலையில் பரிமாறப்படும் பல வகை சைவ விருந்து.", "കേരളത്തിൽ തേങ്ങ പല രൂപത്തിൽ ഉപയോഗിക്കുന്നു; ഒപ്പം കുരുമുളക്, കുടംപുളി, ധാരാളം പുതുമത്സ്യവും. ഉത്സവ സദ്യ വാഴയിലയിൽ വിളമ്പുന്ന പല വിഭവങ്ങളുള്ള സസ്യാഹാരമാണ്.", "ಕೇರಳದ ಅಡುಗೆಯಲ್ಲಿ ತೆಂಗಿನಕಾಯಿ ಹಲವು ರೂಪಗಳಲ್ಲಿ ಬಳಕೆಯಾಗುತ್ತದೆ; ಜೊತೆಗೆ ಕಾಳುಮೆಣಸು, ಕೊಡಂಪುಳಿ ಮತ್ತು ತಾಜಾ ಮೀನು. ಹಬ್ಬದ ಸದ್ಯ ಬಾಳೆ ಎಲೆಯಲ್ಲಿ ಬಡಿಸುವ ಅನೇಕ ಖಾದ್ಯಗಳ ಸಸ್ಯಾಹಾರಿ ಊಟ.", "కేరళ వంటల్లో కొబ్బరిని అనేక రూపాల్లో వాడతారు; దానితో పాటు మిరియాలు, కొడంపులి, పుష్కలంగా తాజా చేపలు. పండుగ సద్య అరటి ఆకులో వడ్డించే అనేక వంటకాల శాకాహార భోజనం.", "केरल में नारियल कई रूपों में इस्तेमाल होता है, साथ में काली मिर्च, कोडमपुली और ढेर सारी ताज़ा मछली। त्योहारी सद्या केले के पत्ते पर परोसा जाने वाला कई व्यंजनों का शाकाहारी भोजन है।"];
  S['region.kerala.ingredients'] = [["Coconut", "Coconut oil", "Black pepper", "Kodampuli (Malabar tamarind)", "Curry leaves", "Fresh fish"], ["தேங்காய்", "தேங்காய் எண்ணெய்", "மிளகு", "குடம்புளி", "கறிவேப்பிலை", "புதிய மீன்"], ["തേങ്ങ", "വെളിച്ചെണ്ണ", "കുരുമുളക്", "കുടംപുളി", "കറിവേപ്പില", "പുതുമത്സ്യം"], ["ತೆಂಗಿನಕಾಯಿ", "ಕೊಬ್ಬರಿ ಎಣ್ಣೆ", "ಕಾಳುಮೆಣಸು", "ಕೊಡಂಪುಳಿ (ಮಲಬಾರ್ ಹುಣಸೆ)", "ಕರಿಬೇವು", "ತಾಜಾ ಮೀನು"], ["కొబ్బరి", "కొబ్బరి నూనె", "మిరియాలు", "కొడంపులి (మలబార్ చింతపండు)", "కరివేపాకు", "తాజా చేపలు"], ["नारियल", "नारियल तेल", "काली मिर्च", "कोडमपुली (मालाबार इमली)", "कढ़ी पत्ता", "ताज़ा मछली"]];
  S['region.kerala.techniques'] = [["Cooking in clay pots (manchatti)", "Steaming in cylindrical moulds (puttu)", "Finishing with raw coconut oil and curry leaves"], ["மண் பானையில் சமைத்தல் (மஞ்சட்டி)", "உருளை அச்சுகளில் ஆவியில் வேகவைத்தல் (புட்டு)", "பச்சைத் தேங்காய் எண்ணெயும் கறிவேப்பிலையும் சேர்த்து முடித்தல்"], ["മൺചട്ടിയിൽ (മൺചട്ടി) പാചകം", "കുഴലിൽ ആവിയിൽ വേവിക്കൽ (പുട്ട്)", "പച്ച വെളിച്ചെണ്ണയും കറിവേപ്പിലയും ചേർത്ത് അവസാനിപ്പിക്കൽ"], ["ಮಣ್ಣಿನ ಪಾತ್ರೆಯಲ್ಲಿ ಅಡುಗೆ (ಮಂಚಟ್ಟಿ)", "ಉರುಳೆ ಆಕಾರದ ಅಚ್ಚಿನಲ್ಲಿ ಹಬೆಯಲ್ಲಿ ಬೇಯಿಸುವುದು (ಪುಟ್ಟು)", "ಹಸಿ ಕೊಬ್ಬರಿ ಎಣ್ಣೆ ಮತ್ತು ಕರಿಬೇವಿನಿಂದ ಮುಗಿಸುವುದು"], ["మట్టి కుండలో వంట (మంచట్టి)", "గొట్టపు అచ్చుల్లో ఆవిరిపై ఉడికించడం (పుట్టు)", "పచ్చి కొబ్బరి నూనె, కరివేపాకుతో ముగించడం"], ["मिट्टी के बर्तन (मंचट्टी) में पकाना", "बेलनाकार साँचे में भाप देना (पुट्टु)", "कच्चे नारियल तेल और कढ़ी पत्ते से अंतिम तड़का"]];

  S['region.andhra-pradesh.name'] = ["Andhra Pradesh", "ஆந்திரப் பிரதேசம்", "ആന്ധ്രപ്രദേശ്", "ಆಂಧ್ರ ಪ್ರದೇಶ", "ఆంధ్రప్రదేశ్", "आंध्र प्रदेश"];
  S['region.andhra-pradesh.intro'] = ["Bold, chilli-forward cooking with tangy gongura and rich pickles.", "காரமான சமையல், புளிப்பான கோங்குரா மற்றும் செறிவான ஊறுகாய்கள்.", "എരിവ് മുന്നിൽ നിൽക്കുന്ന പാചകം, പുളിയുള്ള ഗോങ്ങുര, സമൃദ്ധമായ അച്ചാറുകൾ.", "ಖಾರ ಪ್ರಧಾನ ಅಡುಗೆ, ಹುಳಿ ಗೊಂಗೂರ ಮತ್ತು ಸಮೃದ್ಧ ಉಪ್ಪಿನಕಾಯಿಗಳು.", "ఘాటైన కారం, పుల్లని గోంగూర, రుచికరమైన పచ్చళ్లు.", "तीखी मिर्च वाली पकाई, खट्टी गोंगूरा और समृद्ध अचार।"];
  S['region.andhra-pradesh.about'] = ["Andhra cooking is known for generous chillies, tamarind and sour gongura leaves. Pappu (dal), pachadi (ground chutney) and pickles sit at the heart of everyday meals.", "ஆந்திர சமையல் தாராளமான மிளகாய், புளி, புளிப்பான கோங்குரா இலைகளுக்குப் பெயர் பெற்றது. பப்பு (பருப்பு), பச்சடி, ஊறுகாய் அன்றாட உணவின் மையத்தில் உள்ளன.", "ആന്ധ്ര പാചകം ധാരാളം മുളക്, പുളി, പുളിയുള്ള ഗോങ്ങുര ഇലകൾ എന്നിവയ്ക്ക് പേരുകേട്ടതാണ്. പപ്പു (പരിപ്പ്), പച്ചടി, അച്ചാറുകൾ ദൈനംദിന ഭക്ഷണത്തിന്റെ കേന്ദ്രമാണ്.", "ಆಂಧ್ರ ಅಡುಗೆ ಹೇರಳ ಮೆಣಸಿನಕಾಯಿ, ಹುಣಸೆ ಮತ್ತು ಹುಳಿ ಗೊಂಗೂರ ಎಲೆಗಳಿಗೆ ಹೆಸರುವಾಸಿ. ಪಪ್ಪು (ಬೇಳೆ), ಪಚ್ಚಡಿ ಮತ್ತು ಉಪ್ಪಿನಕಾಯಿ ದೈನಂದಿನ ಊಟದ ಹೃದಯ.", "ఆంధ్ర వంట పుష్కలమైన మిర్చి, చింతపండు, పుల్లని గోంగూర ఆకులకు ప్రసిద్ధి. పప్పు, పచ్చడి, ఊరగాయలు రోజువారీ భోజనానికి గుండెకాయ.", "आंध्र की पकाई भरपूर मिर्च, इमली और खट्टी गोंगूरा पत्तियों के लिए जानी जाती है। पप्पू (दाल), पचड़ी और अचार रोज़ के भोजन का केंद्र हैं।"];
  S['region.andhra-pradesh.ingredients'] = [["Red chillies", "Gongura (sorrel) leaves", "Tamarind", "Toor dal", "Groundnut oil", "Jaggery"], ["சிவப்பு மிளகாய்", "கோங்குரா (புளிச்சக்கீரை) இலைகள்", "புளி", "துவரம் பருப்பு", "கடலை எண்ணெய்", "வெல்லம்"], ["ചുവന്ന മുളക്", "ഗോങ്ങുര (പുളിച്ചീര) ഇലകൾ", "പുളി", "തുവരപ്പരിപ്പ്", "നിലക്കടല എണ്ണ", "ശർക്കര"], ["ಒಣ ಕೆಂಪು ಮೆಣಸಿನಕಾಯಿ", "ಗೊಂಗೂರ (ಪುಂಡಿ ಪಲ್ಯೆ) ಸೊಪ್ಪು", "ಹುಣಸೆಹಣ್ಣು", "ತೊಗರಿ ಬೇಳೆ", "ಕಡಲೆಕಾಯಿ ಎಣ್ಣೆ", "ಬೆಲ್ಲ"], ["ఎండు మిరపకాయలు", "గోంగూర ఆకులు", "చింతపండు", "కందిపప్పు", "వేరుశనగ నూనె", "బెల్లం"], ["लाल मिर्च", "गोंगूरा (अंबाड़ी) पत्ते", "इमली", "अरहर दाल", "मूँगफली का तेल", "गुड़"]];
  S['region.andhra-pradesh.techniques'] = [["Grinding fresh chutneys and pachadis", "Tempering with mustard, cumin and garlic", "Preparing oil-based pickles with spice mixes"], ["புதிய சட்னி, பச்சடிகளை அரைத்தல்", "கடுகு, சீரகம், பூண்டுடன் தாளித்தல்", "மசாலாக் கலவையுடன் எண்ணெய் ஊறுகாய் தயாரித்தல்"], ["പുതിയ ചട്ണിയും പച്ചടിയും അരയ്ക്കൽ", "കടുക്, ജീരകം, വെളുത്തുള്ളി എന്നിവ ചേർത്ത് താളിക്കൽ", "മസാലക്കൂട്ട് ചേർത്ത് എണ്ണ അച്ചാറുകൾ ഉണ്ടാക്കൽ"], ["ತಾಜಾ ಚಟ್ನಿ, ಪಚ್ಚಡಿ ರುಬ್ಬುವುದು", "ಸಾಸಿವೆ, ಜೀರಿಗೆ, ಬೆಳ್ಳುಳ್ಳಿಯಿಂದ ಒಗ್ಗರಣೆ", "ಮಸಾಲೆ ಮಿಶ್ರಣದೊಂದಿಗೆ ಎಣ್ಣೆ ಉಪ್ಪಿನಕಾಯಿ ತಯಾರಿ"], ["తాజా చట్నీలు, పచ్చళ్లు రుబ్బడం", "ఆవాలు, జీలకర్ర, వెల్లుల్లితో తాళింపు", "మసాలా మిశ్రమంతో నూనె ఊరగాయలు తయారు చేయడం"], ["ताज़ी चटनी और पचड़ी पीसना", "सरसों, जीरा और लहसुन का तड़का", "मसाला मिश्रण से तेल वाले अचार बनाना"]];

  S['region.telangana.name'] = ["Telangana", "தெலங்கானா", "തെലങ്കാന", "ತೆಲಂಗಾಣ", "తెలంగాణ", "तेलंगाना"];
  S['region.telangana.intro'] = ["Earthy, rustic flavours built on millets, sesame and tangy tamarind.", "சிறுதானியங்கள், எள், புளிப்புப் புளி ஆகியவற்றால் உருவான மண் மணம் கொண்ட சுவைகள்.", "ചെറുധാന്യങ്ങൾ, എള്ള്, പുളി എന്നിവയിൽ ഒരുങ്ങുന്ന ഗ്രാമീണ രുചികൾ.", "ರಾಗಿ-ಜೋಳದಂತಹ ಸಿರಿಧಾನ್ಯ, ಎಳ್ಳು ಮತ್ತು ಹುಣಸೆಯಿಂದ ಮೂಡುವ ಗ್ರಾಮೀಣ ರುಚಿಗಳು.", "చిరుధాన్యాలు, నువ్వులు, పుల్లని చింతపండుతో పల్లెటూరి రుచులు.", "मोटे अनाज, तिल और खट्टी इमली से बने देहाती स्वाद।"];
  S['region.telangana.about'] = ["Telangana's food leans on millets such as jowar (sorghum) and sajja (pearl millet), sesame, tamarind and dry spice powders. Hearty rotis and rustic curries sit beside festive sweets.", "தெலங்கானா உணவு சோளம், கம்பு போன்ற சிறுதானியங்கள், எள், புளி, உலர் மசாலாத் தூள்களைச் சார்ந்தது. வயிறு நிறைக்கும் ரொட்டிகளும் கிராமியக் குழம்புகளும் பண்டிகை இனிப்புகளுடன் இடம்பெறுகின்றன.", "തെലങ്കാനയിലെ ഭക്ഷണം ജൊവാർ (ചോളം), സജ്ജ (കമ്പ്) പോലുള്ള ചെറുധാന്യങ്ങൾ, എള്ള്, പുളി, ഉണക്ക മസാലപ്പൊടികൾ എന്നിവയെ ആശ്രയിക്കുന്നു. വയറുനിറയ്ക്കുന്ന റൊട്ടികളും ഗ്രാമീണ കറികളും ഉത്സവ മധുരങ്ങൾക്കൊപ്പമുണ്ട്.", "ತೆಲಂಗಾಣದ ಆಹಾರ ಜೋಳ, ಸಜ್ಜೆಯಂತಹ ಸಿರಿಧಾನ್ಯ, ಎಳ್ಳು, ಹುಣಸೆ ಮತ್ತು ಒಣ ಮಸಾಲೆ ಪುಡಿಗಳನ್ನು ಅವಲಂಬಿಸಿದೆ. ಹೊಟ್ಟೆ ತುಂಬಿಸುವ ರೊಟ್ಟಿಗಳು ಮತ್ತು ಗ್ರಾಮೀಣ ಕರಿಗಳು ಹಬ್ಬದ ಸಿಹಿಗಳ ಜೊತೆಗಿವೆ.", "తెలంగాణ ఆహారం జొన్న, సజ్జ వంటి చిరుధాన్యాలు, నువ్వులు, చింతపండు, పొడి మసాలాలపై ఆధారపడుతుంది. కడుపు నింపే రొట్టెలు, పల్లె కూరలు పండుగ మిఠాయిలతో పాటు ఉంటాయి.", "तेलंगाना का भोजन ज्वार और सज्जा (बाजरा) जैसे मोटे अनाज, तिल, इमली और सूखे मसालों पर टिका है। पेट भरने वाली रोटियाँ और देहाती करी त्योहारी मिठाइयों के साथ मिलती हैं।"];
  S['region.telangana.ingredients'] = [["Jowar (sorghum)", "Sajja (pearl millet)", "Sesame seeds", "Tamarind", "Dried red chillies", "Groundnuts"], ["சோளம்", "கம்பு", "எள்", "புளி", "காய்ந்த மிளகாய்", "நிலக்கடலை"], ["ജൊവാർ (ചോളം)", "സജ്ജ (കമ്പ്)", "എള്ള്", "പുളി", "ഉണക്കമുളക്", "നിലക്കടല"], ["ಜೋಳ", "ಸಜ್ಜೆ", "ಎಳ್ಳು", "ಹುಣಸೆಹಣ್ಣು", "ಒಣ ಮೆಣಸಿನಕಾಯಿ", "ಕಡಲೆಕಾಯಿ"], ["జొన్నలు", "సజ్జలు", "నువ్వులు", "చింతపండు", "ఎండు మిరపకాయలు", "వేరుశనగలు"], ["ज्वार", "सज्जा (बाजरा)", "तिल", "इमली", "सूखी लाल मिर्च", "मूँगफली"]];
  S['region.telangana.techniques'] = [["Patting millet rotis by hand", "Grinding spice and sesame powders", "Cooking tangy tamarind-based pulusu"], ["சிறுதானிய ரொட்டிகளை கையால் தட்டுதல்", "மசாலா, எள் தூள் அரைத்தல்", "புளிப்பு புளிக் குழம்பு (புலுசு) சமைத்தல்"], ["ചെറുധാന്യ റൊട്ടികൾ കൈകൊണ്ട് പരത്തൽ", "മസാലയും എള്ളും പൊടിക്കൽ", "പുളിയുള്ള പുലുസു കറി പാകം ചെയ്യൽ"], ["ಸಿರಿಧಾನ್ಯದ ರೊಟ್ಟಿಗಳನ್ನು ಕೈಯಿಂದ ತಟ್ಟುವುದು", "ಮಸಾಲೆ ಮತ್ತು ಎಳ್ಳಿನ ಪುಡಿ ಮಾಡುವುದು", "ಹುಳಿಯ ಪುಲುಸು ತಯಾರಿಸುವುದು"], ["చిరుధాన్య రొట్టెలను చేత్తో వత్తడం", "మసాలా, నువ్వుల పొడులు రుబ్బడం", "పుల్లని పులుసు వండటం"], ["मोटे अनाज की रोटियाँ हाथ से थापना", "मसाले और तिल का पाउडर पीसना", "खट्टा इमली-आधारित पुलुसु पकाना"]];

  S['region.hyderabad.name'] = ["Hyderabad", "ஹைதராபாத்", "ഹൈദരാബാദ്", "ಹೈದರಾಬಾದ್", "హైదరాబాద్", "हैदराबाद"];
  S['region.hyderabad.intro'] = ["Royal Deccan flavours: dum biryani, kebabs, haleem and rich sweets.", "அரச தக்காணச் சுவைகள்: தம் பிரியாணி, கபாப், ஹலீம், செறிவான இனிப்புகள்.", "രാജകീയ ഡെക്കാൻ രുചികൾ: ദം ബിരിയാണി, കബാബ്, ഹലീം, സമൃദ്ധ മധുരങ്ങൾ.", "ರಾಜಮನೆತನದ ದಖ್ಖನ್ ರುಚಿಗಳು: ದಮ್ ಬಿರಿಯಾನಿ, ಕಬಾಬ್, ಹಲೀಮ್ ಮತ್ತು ಸಮೃದ್ಧ ಸಿಹಿಗಳು.", "రాజసమైన దక్కన్ రుచులు: దమ్ బిర్యానీ, కబాబ్‌లు, హలీమ్, సమృద్ధ మిఠాయిలు.", "शाही दक्कनी स्वाद: दम बिरयानी, कबाब, हलीम और समृद्ध मिठाइयाँ।"];
  S['region.hyderabad.about'] = ["Hyderabadi cuisine blends Deccani and Mughlai traditions, with slow dum cooking, whole spices, saffron and nuts. Biryani, haleem and salans are its signatures.", "ஹைதராபாத் உணவு தக்காண மற்றும் முகலாய மரபுகளை இணைக்கிறது; மெல்லிய தம் சமையல், முழு மசாலா, குங்குமப்பூ, கொட்டைகள் இதன் அடையாளங்கள். பிரியாணி, ஹலீம், சாலன் இதன் சிறப்புகள்.", "ഹൈദരാബാദി ഭക്ഷണം ഡെക്കാനി, മുഗൾ പാരമ്പര്യങ്ങൾ കൂട്ടിച്ചേർക്കുന്നു; പതിയെയുള്ള ദം പാചകം, മുഴുവൻ മസാലകൾ, കുങ്കുമപ്പൂവ്, നട്ട്സ് എന്നിവ ഇതിന്റെ മുദ്രകൾ. ബിരിയാണി, ഹലീം, സലാൻ എന്നിവ പ്രധാന വിഭവങ്ങൾ.", "ಹೈದರಾಬಾದಿ ಅಡುಗೆ ದಖ್ಖನಿ ಮತ್ತು ಮೊಘಲ್ ಸಂಪ್ರದಾಯಗಳನ್ನು ಬೆರೆಸುತ್ತದೆ; ನಿಧಾನ ದಮ್ ಅಡುಗೆ, ಪೂರ್ಣ ಮಸಾಲೆ, ಕೇಸರಿ ಮತ್ತು ಬೀಜಗಳು ಇದರ ಗುರುತು. ಬಿರಿಯಾನಿ, ಹಲೀಮ್ ಮತ್ತು ಸಾಲನ್ ಇದರ ವಿಶೇಷಗಳು.", "హైదరాబాదీ వంట దక్కనీ, మొఘలాయి సంప్రదాయాలను కలుపుతుంది; నెమ్మదిగా దమ్ వంట, సంపూర్ణ మసాలాలు, కుంకుమపువ్వు, గింజలు దీని ప్రత్యేకత. బిర్యానీ, హలీమ్, సాలన్‌లు దీని సంతకం వంటకాలు.", "हैदराबादी खाना दक्कनी और मुग़लई परंपराओं का मेल है, जिसमें धीमी दम पकाई, साबुत मसाले, केसर और मेवे हैं। बिरयानी, हलीम और सालन इसकी पहचान हैं।"];
  S['region.hyderabad.ingredients'] = [["Basmati rice", "Saffron", "Whole spices", "Fried onions (birista)", "Mint and coriander", "Peanuts and sesame (for salan)"], ["பாசுமதி அரிசி", "குங்குமப்பூ", "முழு மசாலாப் பொருட்கள்", "வறுத்த வெங்காயம் (பிரிஸ்தா)", "புதினா, கொத்தமல்லி", "வேர்க்கடலை, எள் (சாலனுக்கு)"], ["ബാസ്മതി അരി", "കുങ്കുമപ്പൂവ്", "മുഴുവൻ മസാലകൾ", "വറുത്ത ഉള്ളി (ബിരിസ്ത)", "പുതിന, മല്ലിയില", "നിലക്കടല, എള്ള് (സലാന്)"], ["ಬಾಸ್ಮತಿ ಅಕ್ಕಿ", "ಕೇಸರಿ", "ಪೂರ್ಣ ಮಸಾಲೆಗಳು", "ಹುರಿದ ಈರುಳ್ಳಿ (ಬಿರಿಸ್ತಾ)", "ಪುದೀನ, ಕೊತ್ತಂಬರಿ", "ಕಡಲೆಕಾಯಿ, ಎಳ್ಳು (ಸಾಲನ್‌ಗೆ)"], ["బాస్మతి బియ్యం", "కుంకుమపువ్వు", "సంపూర్ణ మసాలాలు", "వేయించిన ఉల్లి (బిరిస్తా)", "పుదీనా, కొత్తిమీర", "వేరుశనగ, నువ్వులు (సాలన్ కోసం)"], ["बासमती चावल", "केसर", "साबुत मसाले", "तले प्याज़ (बिरिस्ता)", "पुदीना और धनिया", "मूँगफली और तिल (सालन के लिए)"]];
  S['region.hyderabad.techniques'] = [["Dum: slow cooking in a sealed pot", "Frying onions (birista) until deep golden", "Layering rice and meat for biryani"], ["தம்: மூடிய பாத்திரத்தில் மெதுவாக வேகவைத்தல்", "வெங்காயத்தை ஆழ்ந்த பொன்னிறமாக வறுத்தல் (பிரிஸ்தா)", "பிரியாணிக்காக சாதமும் இறைச்சியும் அடுக்குதல்"], ["ദം: അടച്ച പാത്രത്തിൽ പതിയെ വേവിക്കൽ", "ഉള്ളി ഗാഢ സ്വർണനിറമാകുംവരെ വറുക്കൽ (ബിരിസ്ത)", "ബിരിയാണിക്കായി ചോറും മാംസവും അടുക്കിടൽ"], ["ದಮ್: ಮುಚ್ಚಿದ ಪಾತ್ರೆಯಲ್ಲಿ ನಿಧಾನವಾಗಿ ಬೇಯಿಸುವುದು", "ಈರುಳ್ಳಿಯನ್ನು ಗಾಢ ಚಿನ್ನದ ಬಣ್ಣ ಬರುವವರೆಗೆ ಹುರಿಯುವುದು (ಬಿರಿಸ್ತಾ)", "ಬಿರಿಯಾನಿಗೆ ಅನ್ನ ಮತ್ತು ಮಾಂಸವನ್ನು ಪದರ ಪದರವಾಗಿ ಜೋಡಿಸುವುದು"], ["దమ్: మూసిన పాత్రలో నెమ్మదిగా ఉడికించడం", "ఉల్లిని ముదురు బంగారు రంగు వచ్చే వరకు వేయించడం (బిరిస్తా)", "బిర్యానీ కోసం అన్నం, మాంసాన్ని పొరలుగా పేర్చడం"], ["दम: बंद बर्तन में धीमी आँच पर पकाना", "प्याज़ को गहरा सुनहरा होने तक तलना (बिरिस्ता)", "बिरयानी के लिए चावल और मांस की परतें लगाना"]];

  S['region.karnataka.name'] = ["Karnataka", "கர்நாடகா", "കർണാടക", "ಕರ್ನಾಟಕ", "కర్ణాటక", "कर्नाटक"];
  S['region.karnataka.intro'] = ["From Udupi temple meals to Mysore sweets, ragi and coastal seafood.", "உடுப்பி கோயில் உணவுகள் முதல் மைசூர் இனிப்புகள், ராகி, கடற்கரை கடல் உணவுகள் வரை.", "ഉഡുപ്പി ക്ഷേത്രഭക്ഷണം മുതൽ മൈസൂർ മധുരങ്ങൾ, റാഗി, തീരദേശ കടൽവിഭവങ്ങൾ വരെ.", "ಉಡುಪಿ ದೇವಾಲಯದ ಊಟದಿಂದ ಮೈಸೂರು ಸಿಹಿ, ರಾಗಿ ಮತ್ತು ಕರಾವಳಿ ಸಮುದ್ರಾಹಾರದವರೆಗೆ.", "ఉడుపి ఆలయ భోజనాల నుండి మైసూర్ స్వీట్లు, రాగి, తీర సముద్ర వంటకాల వరకు.", "उडुपी के मंदिर भोजन से मैसूर की मिठाइयों, रागी और तटीय समुद्री व्यंजनों तक।"];
  S['region.karnataka.about'] = ["Karnataka's cooking ranges from the jowar rotis of the north to the coconut-and-rice dishes of the coast and the ragi mudde of the south. Mysore and Udupi are known for sweets and vegetarian breakfasts.", "கர்நாடக சமையல் வடக்கின் சோள ரொட்டிகள் முதல் கடற்கரையின் தேங்காய்-அரிசி உணவுகள், தெற்கின் ராகி முத்தே வரை பரவியுள்ளது. மைசூர், உடுப்பி இனிப்புகளுக்கும் சைவ காலை உணவுகளுக்கும் பெயர் பெற்றவை.", "കർണാടക പാചകം വടക്കിലെ ജൊവാർ റൊട്ടി മുതൽ തീരത്തെ തേങ്ങയും ചോറും ചേർന്ന വിഭവങ്ങളും തെക്കിലെ റാഗി മുദ്ദെയും വരെ വ്യാപിച്ചുകിടക്കുന്നു. മൈസൂരും ഉഡുപ്പിയും മധുരങ്ങൾക്കും സസ്യാഹാര പ്രാതലിനും പേരുകേട്ടതാണ്.", "ಕರ್ನಾಟಕದ ಅಡುಗೆ ಉತ್ತರದ ಜೋಳದ ರೊಟ್ಟಿಯಿಂದ ಕರಾವಳಿಯ ತೆಂಗಿನಕಾಯಿ-ಅನ್ನದ ಖಾದ್ಯಗಳು ಮತ್ತು ದಕ್ಷಿಣದ ರಾಗಿ ಮುದ್ದೆಯವರೆಗೆ ಹರಡಿದೆ. ಮೈಸೂರು ಮತ್ತು ಉಡುಪಿ ಸಿಹಿ ಹಾಗೂ ಸಸ್ಯಾಹಾರಿ ಉಪಾಹಾರಕ್ಕೆ ಹೆಸರುವಾಸಿ.", "కర్ణాటక వంట ఉత్తరాన జొన్న రొట్టెల నుండి తీరంలో కొబ్బరి-అన్నం వంటకాలు, దక్షిణాన రాగి ముద్దె వరకు విస్తరించింది. మైసూర్, ఉడుపి స్వీట్లకు, శాకాహార అల్పాహారాలకు ప్రసిద్ధి.", "कर्नाटक की पकाई उत्तर की ज्वार की रोटी से लेकर तट के नारियल-चावल व्यंजनों और दक्षिण के रागी मुद्दे तक फैली है। मैसूर और उडुपी मिठाइयों और शाकाहारी नाश्ते के लिए जाने जाते हैं।"];
  S['region.karnataka.ingredients'] = [["Ragi (finger millet)", "Jowar (sorghum)", "Coconut", "Jaggery", "Curry leaves", "Rice (akki)"], ["ராகி (கேழ்வரகு)", "சோளம்", "தேங்காய்", "வெல்லம்", "கறிவேப்பிலை", "அரிசி (அக்கி)"], ["റാഗി (പഞ്ഞപ്പുല്ല്)", "ജൊവാർ (ചോളം)", "തേങ്ങ", "ശർക്കര", "കറിവേപ്പില", "അരി (അക്കി)"], ["ರಾಗಿ", "ಜೋಳ", "ತೆಂಗಿನಕಾಯಿ", "ಬೆಲ್ಲ", "ಕರಿಬೇವು", "ಅಕ್ಕಿ"], ["రాగులు", "జొన్నలు", "కొబ్బరి", "బెల్లం", "కరివేపాకు", "బియ్యం (అక్కి)"], ["रागी", "ज्वार", "नारियल", "गुड़", "कढ़ी पत्ता", "चावल (अक्की)"]];
  S['region.karnataka.techniques'] = [["Steaming and griddling rice-based dishes", "Making ragi mudde by stirring and shaping", "Cooking sugar syrups for sweets"], ["அரிசி உணவுகளை ஆவியில் வேகவைத்தல், தோசைக்கல்லில் சுடுதல்", "கிளறி உருட்டி ராகி முத்தே செய்தல்", "இனிப்புகளுக்கு சர்க்கரைப் பாகு காய்ச்சுதல்"], ["അരി വിഭവങ്ങൾ ആവിയിൽ വേവിക്കലും ചട്ടിയിൽ ചുടലും", "ഇളക്കി ഉരുട്ടി റാഗി മുദ്ദെ ഉണ്ടാക്കൽ", "മധുരങ്ങൾക്ക് പഞ്ചസാര പാനി കാച്ചൽ"], ["ಅಕ್ಕಿ ಖಾದ್ಯಗಳನ್ನು ಹಬೆಯಲ್ಲಿ ಬೇಯಿಸುವುದು, ಕಾವಲಿಯಲ್ಲಿ ಹುರಿಯುವುದು", "ಕೈಯಾಡಿಸಿ ಉರುಟು ಮಾಡಿ ರಾಗಿ ಮುದ್ದೆ ತಯಾರಿಸುವುದು", "ಸಿಹಿಗಳಿಗೆ ಸಕ್ಕರೆ ಪಾಕ ಕಾಯಿಸುವುದು"], ["బియ్యం వంటకాలను ఆవిరిపై ఉడికించడం, పెనంపై కాల్చడం", "కలుపుతూ ముద్దగా చేసి రాగి ముద్దె తయారు చేయడం", "మిఠాయిల కోసం చక్కెర పాకం కాచడం"], ["चावल के व्यंजनों को भाप देना और तवे पर सेंकना", "चलाकर और गोल आकार देकर रागी मुद्दे बनाना", "मिठाइयों के लिए चीनी की चाशनी पकाना"]];

  S['diet.contains.egg'] = ["Contains egg", "முட்டை உள்ளது", "മുട്ട അടങ്ങിയത്", "ಮೊಟ್ಟೆ ಒಳಗೊಂಡಿದೆ", "గుడ్డు ఉంది", "अंडा शामिल"];
